          isShowing = false;
        } catch {
          /* not a showing popover */
        }
        if (isShowing) {
          return;
        }
        try {
          el.showPopover();
        } catch {
          /* already showing */
        }
        if (hadFocus) {
          active.focus({preventScroll: true});
        }
        return;
      }
      if (!isShowing) {
        try {
          el.showPopover();
        } catch {
          /* already showing */
        }
      }
