    dispose(): void {
      clearHighlightTimer();
      clearFlash();
      setHighlighted(false);
      finish();
    },

    get selectionLock() {
      return options.selectionLock;
    },
  };
  if (options.keepsTouch === true) {
    // Only the tracked touch whose press was delivered is kept.
    return Object.assign(tracker, {
      keepsTouch: (id: number) => isKept && touchId === id,
    });
