  override get isDiscrete(): boolean {
    return true;
  }

  override get nativeTouchBehavior(): NativeTouchBehavior {
    return MANIPULATION;
  }

  /** Taps completed so far in the current sequence. */
  get completedTaps(): number {
    return this.tapCount;
