function canMoveX(
  entry: Pick<ChainEntry, 'element' | 'isRtl'>,
  dx: number,
): boolean {
  const {element} = entry;
  const overflow = element.scrollWidth - element.clientWidth;
  if (overflow <= EDGE_TOLERANCE) {
    return false;
