  if (isScaleConfig(config)) {
    const scale = expandMotionScale(config);
    Object.assign(tokens, scale);
    if (knobs.tempoIsSet) {
      for (const [name, value] of Object.entries(scale)) {
        if (name.startsWith('--duration-')) {
          tokens[preTempoName(name)] = value;
