    CHARACTER_EASE[knobs.character] ??
    (config.character != null
      ? (scaleEasing ?? easeDefaults['--ease-standard'])
      : scaleEasing);
  if (ease != null) {
    tokens['--ease-entrance'] = ease;
    tokens['--ease-move'] = ease;
  }
  return tokens;
